export interface GlyphOptions {
  directory?: string;
  className?: string;
  label?: string;
}

export interface GlyphDescriptor {
  src: string;
  className: string;
  alt: string;
}

export function createGlyphDescriptor(
  name: string,
  options: GlyphOptions = {},
): GlyphDescriptor {
  if (typeof name !== "string" || !/^[A-Za-z0-9][A-Za-z0-9_-]*$/.test(name)) {
    throw new TypeError("invalid glyph name");
  }
  if (typeof options !== "object" || options === null || Array.isArray(options)) {
    throw new TypeError("options must be an object");
  }
  if (options.directory !== undefined &&
      (typeof options.directory !== "string" || options.directory.length === 0)) {
    throw new TypeError("invalid directory");
  }
  if (options.className !== undefined && typeof options.className !== "string") {
    throw new TypeError("invalid className");
  }
  if (options.label !== undefined && typeof options.label !== "string") {
    throw new TypeError("invalid label");
  }

  const rawDirectory = options.directory ?? "/assets/glyphs";
  const directory = rawDirectory.replace(/\/+$/, "");
  if (directory.length === 0) {
    throw new TypeError("invalid directory");
  }
  const customClass = options.className?.trim() ?? "";

  return {
    src: `${directory}/${name}.png`,
    className: customClass ? `glyph-image ${customClass}` : "glyph-image",
    alt: options.label ?? "",
  };
}

