import { createGlyphDescriptor } from './solution';
import type { GlyphDescriptor, GlyphOptions } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function assertDescriptor(actual: GlyphDescriptor, src: string, className: string, alt: string): void {
  assert(actual.src === src, 'unexpected src');
  assert(actual.className === className, 'unexpected className');
  assert(actual.alt === alt, 'unexpected alt');
}

function assertThrowsTypeError(action: () => unknown, message: string): void {
  try {
    action();
  } catch (error) {
    assert(error instanceof TypeError, `${message}: expected TypeError`);
    return;
  }
  throw new Error(`${message}: expected an exception`);
}

assertDescriptor(
  createGlyphDescriptor('user_2-main'),
  '/assets/glyphs/user_2-main.svg',
  'glyph-image',
  '',
);

const options: GlyphOptions = {
  directory: '/custom/icons///',
  className: '  highlighted large  ',
  label: 'Profile glyph',
};
const descriptor = createGlyphDescriptor('Profile', options);
assertDescriptor(descriptor, '/custom/icons/Profile.svg', 'glyph-image highlighted large', 'Profile glyph');
assert(options.directory === '/custom/icons///', 'directory option must not be mutated');
assert(options.className === '  highlighted large  ', 'class option must not be mutated');

assertDescriptor(
  createGlyphDescriptor('a', { className: '   ', directory: 'relative/' }),
  'relative/a.svg',
  'glyph-image',
  '',
);

for (const name of ['', '-bad', '_bad', 'has space', 'bad.dot', 'slash/name', 'é']) {
  assertThrowsTypeError(() => createGlyphDescriptor(name), `invalid name ${name}`);
}
assertThrowsTypeError(() => createGlyphDescriptor(4 as unknown as string), 'non-string name');
assertThrowsTypeError(() => createGlyphDescriptor('ok', { directory: '' }), 'empty directory');
assertThrowsTypeError(() => createGlyphDescriptor('ok', { directory: 3 } as unknown as GlyphOptions), 'non-string directory');
assertThrowsTypeError(() => createGlyphDescriptor('ok', { className: false } as unknown as GlyphOptions), 'non-string className');
assertThrowsTypeError(() => createGlyphDescriptor('ok', { label: null } as unknown as GlyphOptions), 'non-string label');
assertThrowsTypeError(() => createGlyphDescriptor('ok', null as unknown as GlyphOptions), 'null options');

